CREATE TABLE public.audit_ai_access_state (id text PRIMARY KEY CHECK (id = 'audit-review'), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.audit_ai_access_state TO service_role; REVOKE ALL ON public.audit_ai_access_state FROM anon, authenticated; ALTER TABLE public.audit_ai_access_state ENABLE ROW LEVEL SECURITY; COMMENT ON TABLE public.audit_ai_access_state IS 'Durable terminal provider denial state for manual audit AI review; privileged server access only.';